        } else if (characters[0] == '(') {
            mode = 1;
        }
        for (int i = 0; i < n; i++) {
            if (mode == 0) {
                if (characters[i] == '_') {
                    index++;
                } else {
                    if (characters[i] != '(') {
                        counts[index]++;
                    } else if (characters[i] == '(') {
                        mode = 1;
                    } else if (characters[i] == ')') {
                        mode = 0;
                    }
                }
            } else {
                if (characters[i] == ')') {
                    mode = 0;
                    index++;
